with card_content(display_order, question_text, question_translation, answer_examples) as (
  values
    (31, 'What is your favorite book?', 'Qual é o seu livro favorito?', '[{"answer":"My favorite book is The Little Prince.","translation":"Meu livro favorito é O Pequeno Príncipe.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I really like 1984.","translation":"Eu gosto muito de 1984.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I don''t have just one favorite book.","translation":"Eu não tenho apenas um livro favorito.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"One of my favorites is The Alchemist.","translation":"Um dos meus favoritos é O Alquimista.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"It changes over time, but right now it''s a biography I''m reading.","translation":"Isso muda com o tempo, mas agora é uma biografia que estou lendo.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (32, 'Do you like watching movies?', 'Você gosta de assistir a filmes?', '[{"answer":"Yes, I love movies.","translation":"Sim, eu adoro filmes.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Yes, I watch movies every weekend.","translation":"Sim, eu assisto a filmes todo fim de semana.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I like movies, especially comedies.","translation":"Eu gosto de filmes, especialmente comédias.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Sometimes, but I prefer series.","translation":"Às vezes, mas eu prefiro séries.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Not very often, but I enjoy a good movie with friends.","translation":"Não com muita frequência, mas gosto de um bom filme com amigos.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (33, 'What kind of movies do you like?', 'Que tipo de filmes você gosta?', '[{"answer":"I like comedies.","translation":"Eu gosto de comédias.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I enjoy action movies.","translation":"Eu gosto de filmes de ação.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I love science fiction.","translation":"Eu adoro ficção científica.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I usually watch dramas and thrillers.","translation":"Eu geralmente assisto a dramas e suspenses.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I like different genres, but documentaries are my favorite.","translation":"Eu gosto de gêneros diferentes, mas documentários são meus favoritos.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (34, 'What is your favorite movie?', 'Qual é o seu filme favorito?', '[{"answer":"My favorite movie is Interstellar.","translation":"Meu filme favorito é Interestelar.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I really like The Godfather.","translation":"Eu gosto muito de O Poderoso Chefão.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I don''t have a single favorite.","translation":"Eu não tenho um único favorito.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"One of my favorites is Toy Story.","translation":"Um dos meus favoritos é Toy Story.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Right now, my favorite is a movie I watched recently.","translation":"No momento, meu favorito é um filme que assisti recentemente.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (35, 'Do you watch TV series?', 'Você assiste a séries?', '[{"answer":"Yes, I watch a lot of series.","translation":"Sim, eu assisto a muitas séries.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Yes, especially on weekends.","translation":"Sim, especialmente nos fins de semana.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Sometimes, when I have time.","translation":"Às vezes, quando tenho tempo.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Not really. I prefer movies.","translation":"Na verdade, não. Eu prefiro filmes.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I usually watch one or two episodes at night.","translation":"Eu geralmente assisto a um ou dois episódios à noite.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (36, 'What is your favorite TV series?', 'Qual é a sua série favorita?', '[{"answer":"My favorite series is Friends.","translation":"Minha série favorita é Friends.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I really like Breaking Bad.","translation":"Eu gosto muito de Breaking Bad.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I don''t have one favorite series.","translation":"Eu não tenho uma série favorita.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"One of my favorites is The Office.","translation":"Uma das minhas favoritas é The Office.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"My favorite changes, but I''m really enjoying my current series.","translation":"Minha favorita muda, mas estou gostando muito da série que assisto atualmente.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (37, 'Do you like listening to music?', 'Você gosta de ouvir música?', '[{"answer":"Yes, I listen to music every day.","translation":"Sim, eu ouço música todos os dias.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Yes, I love music.","translation":"Sim, eu adoro música.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I usually listen to music while working.","translation":"Eu geralmente ouço música enquanto trabalho.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Sometimes, especially when I''m driving.","translation":"Às vezes, especialmente quando estou dirigindo.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Yes, music helps me relax.","translation":"Sim, a música me ajuda a relaxar.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (38, 'What kind of music do you like?', 'Que tipo de música você gosta?', '[{"answer":"I like pop music.","translation":"Eu gosto de música pop.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I enjoy rock.","translation":"Eu gosto de rock.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I listen to Brazilian music a lot.","translation":"Eu ouço bastante música brasileira.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I like jazz and classical music.","translation":"Eu gosto de jazz e música clássica.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"My taste is pretty varied, so I listen to many different styles.","translation":"Meu gosto é bem variado, então ouço muitos estilos diferentes.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (39, 'Who is your favorite singer or band?', 'Quem é o seu cantor, cantora ou banda favorita?', '[{"answer":"My favorite band is Coldplay.","translation":"Minha banda favorita é Coldplay.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I really like Adele.","translation":"Eu gosto muito da Adele.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I don''t have a favorite singer.","translation":"Eu não tenho um cantor ou cantora favorito/a.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"One of my favorite artists is Bruno Mars.","translation":"Um dos meus artistas favoritos é Bruno Mars.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"It changes a lot, but lately I''ve been listening to Taylor Swift.","translation":"Isso muda bastante, mas ultimamente tenho ouvido Taylor Swift.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (40, 'What is your favorite song?', 'Qual é a sua música favorita?', '[{"answer":"My favorite song is Yellow.","translation":"Minha música favorita é Yellow.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I really like Imagine.","translation":"Eu gosto muito de Imagine.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I don''t have just one favorite song.","translation":"Eu não tenho apenas uma música favorita.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"One of my favorites is Viva la Vida.","translation":"Uma das minhas favoritas é Viva la Vida.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"It depends on my mood, so my favorite changes often.","translation":"Depende do meu humor, então minha favorita muda com frequência.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb)
)
update public.conversation_questions as question
set question_text=content.question_text, question_translation=content.question_translation, answer_examples=content.answer_examples
from card_content as content where question.display_order=content.display_order;
